submit_claim.definition:
{
  "description": "Send a claim to Hollowmere Pet Insurance for a treatment the clinic gave.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "properties": {
      "invoiceTotal": {
        "description": "The invoice total in pounds, for example 240",
        "type": "number"
      },
      "patientId": {
        "description": "Patient id, for example P-0001",
        "type": "string"
      },
      "treatment": {
        "description": "What the clinic did, for example Dental scale and polish",
        "type": "string"
      }
    },
    "required": [
      "patientId",
      "treatment",
      "invoiceTotal"
    ],
    "type": "object"
  },
  "name": "submit_claim"
}

